/// Holds its collaborators as providers and acquires them when used.
pub struct Rex {
    collar: forge_foundation::ProviderRef<dyn Collar>,
    chip: forge_foundation::ProviderRef<dyn Chip>,
    training: forge_foundation::ProviderRef<dyn Training>,
}

impl Dog for Rex {
    fn owner(&self, request: Encounter) -> Result<OwnerName, FoundationError> {
        let answer = self
            .collar
            .provide()?
            .read(Glance(request.0.clone()))?
            .0;
        if !answer.is_empty() {
            return Ok(OwnerName(answer));
        }
        let answer = self
            .chip
            .provide()?
            .scan(Scan(request.0.clone()))?
            .0;
        if !answer.is_empty() {
            return Ok(OwnerName(answer));
        }
        Ok(OwnerName("stray".to_string()))
    }
    fn settle(&self, request: Crate) -> Result<Mood, FoundationError> {
        let answer = self
            .training
            .provide()?
            .settle(Crate(request.0.clone()))?
            .0;
        if !answer.is_empty() {
            return Ok(Mood(answer));
        }
        Ok(Mood("whines".to_string()))
    }
}

/// Holds its collaborators as providers and acquires them when used.
pub struct BoardingKennel {
    dog: forge_foundation::ProviderRef<dyn Dog>,
}

impl Kennel for BoardingKennel {
    fn board(&self, request: Stay) -> Result<Ticket, FoundationError> {
        let answer = self
            .dog
            .provide()?
            .owner(Encounter(request.0.clone()))?
            .0;
        if !answer.is_empty() {
            return Ok(Ticket(answer));
        }
        Ok(Ticket("".to_string()))
    }
}

/// Decorator by composition: same port, wraps the inner instance.
pub struct Sitter {
    inner: Arc<dyn Dog>,
    log: forge_foundation::CallLog,
}

impl Dog for Sitter {
    fn owner(&self, request: Encounter) -> Result<OwnerName, FoundationError> {
        self.log.record();
        self.inner.owner(request)
    }
    fn settle(&self, request: Crate) -> Result<Mood, FoundationError> {
        self.log.record();
        self.inner.settle(request)
    }
}

