impl Assemble for DogScene {
    type Env = DogEnv;

    /// Every environment runs the same step: stage one group per bound port,
    /// freeze (which rejects a missing required collaborator), then construct.
    fn assemble(env: DogEnv) -> Result<Self, FoundationError> {
        match env {
            DogEnv::Prod => assemble_prod(),
            DogEnv::Yard => assemble_yard(),
            DogEnv::Shelter => assemble_shelter(),
            DogEnv::Lonely => assemble_lonely(),
            DogEnv::Test => assemble_test(),
        }
    }
}

