fn assemble_prod() -> Result<DogScene, FoundationError> {
    let _plan = EnvBuilder::new("prod")
        .stage("collar", &[])?
        .stage("chip", &[])?
        .stage("training", &[])?
        .stage("dog", &[])?
        .stage("kennel", &["dog"])?
        .freeze()?;
    let sitter = forge_foundation::CallLog::default();
    let collar: Slot<dyn Collar> = {
        let factory = LeatherCollarFactory;
        let provider =
            forge_foundation::SingletonProvider::<dyn Collar>::from_factory(&factory)?;
        Slot::bound(Arc::new(provider))
    };
    let chip: Slot<dyn Chip> = {
        let factory = RegistryChipFactory;
        let provider =
            forge_foundation::LazySingletonProvider::<dyn Chip, _>::new(factory);
        Slot::bound(Arc::new(provider))
    };
    let training: Slot<dyn Training> = {
        let factory = CrateTrainedFactory;
        let provider = forge_foundation::TransientProvider::<dyn Training, _>::new(factory);
        Slot::bound(Arc::new(provider))
    };
    let dog: Slot<dyn Dog> = {
        let factory = RexFactory {
            collar: collar.provider()?,
            chip: chip.provider()?,
            training: training.provider()?,
        };
        let factory = forge_foundation::Decorated::new(
            factory,
            SitterDecorator {
                log: sitter.clone(),
            },
        );
        let provider =
            forge_foundation::SingletonProvider::<dyn Dog>::from_factory(&factory)?;
        Slot::bound(Arc::new(provider))
    };
    let kennel: Slot<dyn Kennel> = {
        let factory = BoardingKennelFactory {
            dog: dog.provider()?,
        };
        let provider =
            forge_foundation::SingletonProvider::<dyn Kennel>::from_factory(&factory)?;
        Slot::bound(Arc::new(provider))
    };
    Ok(DogScene {
        env: DogEnv::Prod,
        collar,
        chip,
        training,
        dog,
        kennel,
        engraved_collar: forge_foundation::AssistedProvider::new(EngravedCollarFactory),
        sitter,
    })
}

