// ---- Client example: only the container and its providers ---------------------

/// Walks every environment the way an application would: assemble the
/// container, ask a slot for its provider, acquire, call the port.
pub fn client() -> Result<Vec<String>, FoundationError> {
    let mut lines = Vec::new();
    let scene = DogScene::assemble(DogEnv::Prod)?;
    lines.push(format!(
        "prod collar.read -> {}",
        scene
            .collar()
            .provider()?
            .provide()?
            .read(Glance("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "prod chip.scan -> {}",
        scene
            .chip()
            .provider()?
            .provide()?
            .scan(Scan("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "prod training.settle -> {}",
        scene
            .training()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "prod dog.owner -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .owner(Encounter("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "prod dog.settle -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "prod kennel.board -> {}",
        scene
            .kennel()
            .provider()?
            .provide()?
            .board(Stay("client".to_string()))?
            .0
    ));
    let scene = DogScene::assemble(DogEnv::Yard)?;
    lines.push(format!(
        "yard collar.read -> {}",
        scene
            .collar()
            .provider()?
            .provide()?
            .read(Glance("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "yard chip.scan -> {}",
        scene
            .chip()
            .provider()?
            .provide()?
            .scan(Scan("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "yard training.settle -> {}",
        scene
            .training()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "yard dog.owner -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .owner(Encounter("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "yard dog.settle -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    let scene = DogScene::assemble(DogEnv::Shelter)?;
    lines.push(format!(
        "shelter collar.read -> {}",
        scene
            .collar()
            .provider()?
            .provide()?
            .read(Glance("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "shelter chip.scan -> {}",
        scene
            .chip()
            .provider()?
            .provide()?
            .scan(Scan("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "shelter training.settle -> {}",
        scene
            .training()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "shelter dog.owner -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .owner(Encounter("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "shelter dog.settle -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    match DogScene::assemble(DogEnv::Lonely) {
        Ok(_) => lines.push("lonely assembled".to_string()),
        Err(error) => lines.push(format!("lonely refused: {error}")),
    }
    let scene = DogScene::assemble(DogEnv::Test)?;
    lines.push(format!(
        "test collar.read -> {}",
        scene
            .collar()
            .provider()?
            .provide()?
            .read(Glance("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "test chip.scan -> {}",
        scene
            .chip()
            .provider()?
            .provide()?
            .scan(Scan("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "test training.settle -> {}",
        scene
            .training()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "test dog.owner -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .owner(Encounter("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "test dog.settle -> {}",
        scene
            .dog()
            .provider()?
            .provide()?
            .settle(Crate("client".to_string()))?
            .0
    ));
    lines.push(format!(
        "test kennel.board -> {}",
        scene
            .kennel()
            .provider()?
            .provide()?
            .board(Stay("client".to_string()))?
            .0
    ));
    let scene = DogScene::assemble(DogEnv::Prod)?;
    let variant = scene.engraved_collar().get("client-owner".to_string())?;
    lines.push(format!(
        "engraved_collar(client-owner).read -> {}",
        variant.read(Glance("client".to_string()))?.0
    ));
    Ok(lines)
}

// ---- Structural tests ---------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use forge_foundation::Provide;

    #[test]
    fn every_environment_freezes_or_names_what_is_missing() {
        assert!(wire_prod().is_ok(), "prod should assemble");
        assert!(wire_yard().is_ok(), "yard should assemble");
        assert!(wire_shelter().is_ok(), "shelter should assemble");
        assert!(
            matches!(wire_lonely(), Err(FoundationError::Freeze(_))),
            "lonely should be rejected at freeze"
        );
        assert!(wire_test().is_ok(), "test should assemble");
    }

    #[test]
    fn leather_collar_singleton_is_shared() {
        let provider =
            forge_foundation::SingletonProvider::<dyn Collar>::from_factory(&LeatherCollarFactory)
                .unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn bare_neck_singleton_is_shared() {
        let provider =
            forge_foundation::SingletonProvider::<dyn Collar>::from_factory(&BareNeckFactory)
                .unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn registry_chip_lazy_singleton_waits_for_first_use() {
        let provider = forge_foundation::LazySingletonProvider::<dyn Chip, _>::new(RegistryChipFactory);
        assert!(!provider.is_initialized());
        let first = provider.provide().unwrap();
        assert!(provider.is_initialized());
        assert!(Arc::ptr_eq(&first, &provider.provide().unwrap()));
    }

    #[test]
    fn unchipped_singleton_is_shared() {
        let provider =
            forge_foundation::SingletonProvider::<dyn Chip>::from_factory(&UnchippedFactory)
                .unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn crate_trained_transient_is_fresh_each_time() {
        let provider = forge_foundation::TransientProvider::<dyn Training, _>::new(CrateTrainedFactory);
        assert!(!Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn untrained_singleton_is_shared() {
        let provider =
            forge_foundation::SingletonProvider::<dyn Training>::from_factory(&UntrainedFactory)
                .unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn pretend_dog_singleton_is_shared() {
        let provider =
            forge_foundation::SingletonProvider::<dyn Dog>::from_factory(&PretendDogFactory)
                .unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn engraved_collar_assisted_variants_carry_their_arguments() {
        let provider = forge_foundation::AssistedProvider::new(EngravedCollarFactory);
        let first = provider.get("first".to_string()).unwrap();
        let second = provider.get("second".to_string()).unwrap();
        assert!(!Arc::ptr_eq(&first, &second));
        let probe = || Glance("probe".to_string());
        assert_eq!(first.read(probe()).unwrap().0, "first");
        assert_eq!(second.read(probe()).unwrap().0, "second");
    }

    #[test]
    fn prod_slots_keep_their_lifecycles() {
        let scene = wire_prod().unwrap();
        let provider = scene.collar().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.chip().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.training().provider().unwrap();
        assert!(!Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.dog().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let before = scene.sitter().calls();
        let probe = Encounter("probe".to_string());
        provider.provide().unwrap().owner(probe).unwrap();
        assert_eq!(scene.sitter().calls(), before + 1);
        let provider = scene.kennel().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn yard_slots_keep_their_lifecycles() {
        let scene = wire_yard().unwrap();
        let provider = scene.collar().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.collar().is_default());
        let provider = scene.chip().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.chip().is_default());
        let provider = scene.training().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.training().is_default());
        let provider = scene.dog().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.kennel().provider().is_err());
    }

    #[test]
    fn shelter_slots_keep_their_lifecycles() {
        let scene = wire_shelter().unwrap();
        let provider = scene.collar().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.collar().is_default());
        let provider = scene.chip().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.training().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.training().is_default());
        let provider = scene.dog().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        assert!(scene.kennel().provider().is_err());
    }

    #[test]
    fn test_slots_keep_their_lifecycles() {
        let scene = wire_test().unwrap();
        let provider = scene.collar().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.chip().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.training().provider().unwrap();
        assert!(!Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.dog().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
        let provider = scene.kennel().provider().unwrap();
        assert!(Arc::ptr_eq(&provider.provide().unwrap(), &provider.provide().unwrap()));
    }

    #[test]
    fn client_example_runs() {
        assert!(!client().unwrap().is_empty());
    }
}
